      {[0, 90, 180, 270].map(a => { const [x, y] = polar(a - 90, 55); return <path key={a} d="M0 -5 L4 0 L0 5 L-4 0 Z" transform={`translate(${x} ${y}) rotate(${a})`} fill={GOLD} stroke="#6B4A00" strokeWidth="0.8" />; })}
