const frameTile = (on) => ({
  display: "flex", flexDirection: "column", alignItems: "center", gap: 8, padding: "16px 4px 12px", borderRadius: 18, cursor: "pointer", color: "#fff",
  background: "rgba(255,255,255,0.06)", border: `2px solid ${on ? "var(--accent-soft)" : "rgba(255,255,255,0.12)"}`,
});

const AvatarFrame = ({ profile, size = 76, simple = false }) => {
  const frame = FRAMES.find(f => f.id === profile.frame) || FRAMES[0];
  const photo = (d) => (
    <div style={{ width: d, height: d, borderRadius: "50%", overflow: "hidden", flexShrink: 0,
      background: profile.avatar ? "transparent" : "var(--accent)", display: "flex", alignItems: "center", justifyContent: "center",
      fontSize: d * 0.34, fontWeight: 700, color: "#fff" }}>
      {profile.avatar
        ? <img src={profile.avatar} alt="" style={{ width: "100%", height: "100%", objectFit: "cover" }} />
        : profile.name.slice(0, 2).toUpperCase()}
    </div>
  );
  if (simple) return (
    <div style={{ width: size, height: size, flexShrink: 0, borderRadius: "50%", padding: 2.5, boxSizing: "border-box", background: frame.ring, boxShadow: "0 2px 8px rgba(0,0,0,0.45)" }}>
      {photo(size - 5)}
    </div>
  );
  const k = size / 100;
  if (frame.img) {
    const box = 140 * k, g = frame.geo, d = 2 * g.r * box;
    return (
      <div style={{ position: "relative", width: box, height: box, flexShrink: 0 }}>
        <div style={{ position: "absolute", left: g.cx * box - d / 2, top: g.cy * box - d / 2 }}>{photo(d)}</div>
        <img src={frame.img} alt="" draggable={false}
          style={{ position: "absolute", inset: 0, width: "100%", height: "100%", pointerEvents: "none", userSelect: "none", filter: "drop-shadow(0 3px 6px rgba(0,0,0,0.4))" }} />
      </div>
    );
  }
  return (
    <div style={{ position: "relative", width: 140 * k, height: 140 * k, flexShrink: 0 }}>
      <div style={{ position: "absolute", left: 20 * k, top: 20 * k }}>{photo(100 * k)}</div>
      <svg viewBox="0 0 140 140" width="100%" height="100%" aria-hidden="true"
        style={{ position: "absolute", inset: 0, overflow: "visible", filter: "drop-shadow(0 3px 6px rgba(0,0,0,0.4))" }}>
        <defs>
          <linearGradient id="fGold" x1="0" y1="0" x2="1" y2="1">
            <stop offset="0" stopColor="#FFF3B0" /><stop offset="0.35" stopColor="#F6C945" /><stop offset="0.7" stopColor="#B8860B" /><stop offset="1" stopColor="#FFE08A" />
          </linearGradient>
        </defs>
        {frame.art()}
      </svg>
    </div>
  );
};

