const Poster = ({ a, onClick }) => (
  <button onClick={onClick} style={{ background: "none", border: "none", padding: 0, cursor: "pointer", textAlign: "left", color: "#fff", minWidth: 0 }}>
    <Cover a={a} />
    <div style={{ fontSize: 12.5, fontWeight: 600, marginTop: 6, display: "-webkit-box", WebkitLineClamp: 2, WebkitBoxOrient: "vertical", overflow: "hidden" }}>{a.title}</div>
    <div style={{ fontSize: 11, color: dim }}>{(a.episodes || []).length} episode</div>
  </button>
);

const chip = (on) => ({ border: "none", cursor: "pointer", padding: "7px 14px", borderRadius: 99, fontSize: 12.5, fontWeight: 600, whiteSpace: "nowrap", flexShrink: 0, color: "#fff", background: on ? "var(--accent)" : "rgba(255,255,255,0.08)" });

const HomeScreen = ({ catalog, status, onOpen, reload }) => {
  const [q, setQ] = useState("");
  const [g, setG] = useState("");
  const genres = useMemo(() => [...new Set(catalog.flatMap(a => a.genres || []))].sort(), [catalog]);
  const list = catalog.filter(a => (!g || (a.genres || []).includes(g)) && a.title.toLowerCase().includes(q.trim().toLowerCase()));
  return (
    <div style={{ padding: "4px 18px 120px" }}>
      <div style={{ position: "relative" }}>
        <input value={q} onChange={e => setQ(e.target.value)} placeholder="Cari anime…" aria-label="Cari anime" style={{ ...inputStyle, paddingLeft: 40 }} />
        <span style={{ position: "absolute", left: 12, top: 11, color: dim }}><IcSearch s={18} /></span>
      </div>
      {genres.length > 0 && (
        <div style={{ display: "flex", gap: 8, overflowX: "auto", margin: "12px 0 4px" }}>
          {["", ...genres].map(x => <button key={x || "all"} onClick={() => setG(x)} style={chip(g === x)}>{x || "Semua"}</button>)}
        </div>
      )}
      {status === "loading" && <Msg>Memuat katalog…</Msg>}
      {status === "error" && <Msg>Katalog tidak bisa dimuat.<br /><button onClick={reload} style={{ ...chip(true), marginTop: 12 }}>Coba lagi</button></Msg>}
      {status === "ok" && catalog.length === 0 && <Msg><div className="disp" style={{ fontSize: 20, fontWeight: 700, color: "#fff", marginBottom: 6 }}>Belum ada anime</div>Anime yang diposting lewat halaman admin akan muncul di sini.</Msg>}
      {status === "ok" && catalog.length > 0 && list.length === 0 && <Msg>Tidak ada anime yang cocok.</Msg>}
      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill,minmax(104px,1fr))", gap: 14, marginTop: 14 }}>
        {list.map(a => <Poster key={a.id} a={a} onClick={() => onOpen(a)} />)}
      </div>
    </div>
  );
};

const DetailScreen = ({ a, hist, onClose, onWatch }) => {
  const [ep, setEp] = useState(null);
  const eps = a.episodes || [];
  const idx = eps.findIndex(e => e.n === ep);
  const cur = idx >= 0 ? eps[idx] : null;
  const seen = hist[a.id]?.eps || [];
  const play = (e) => { setEp(e.n); onWatch(a, e); };
  const resume = eps.find(e => e.n === hist[a.id]?.ep) || eps[0];
  const pl = { width: "100%", aspectRatio: "16/9", background: "#000", borderRadius: 14, display: "block", border: "none" };
  return (
    <div role="dialog" aria-modal="true" aria-label={a.title} style={{ position: "fixed", inset: 0, zIndex: 100, background: "var(--bg)", overflowY: "auto", paddingBottom: 40 }}>
      <div style={{ position: "sticky", top: 0, zIndex: 2, padding: "calc(env(safe-area-inset-top,0px) + 10px) 14px 10px", background: "rgba(var(--bg-rgb),0.92)", backdropFilter: "blur(20px)", display: "flex", alignItems: "center", gap: 10 }}>
        <button aria-label="Tutup" onClick={onClose} style={iconBtn}><IcClose s={20} /></button>
        <div style={{ fontWeight: 700, fontSize: 16, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{a.title}</div>
      </div>
      <div style={{ padding: "4px 18px" }}>
        {cur && (
          <div style={{ marginBottom: 16 }}>
            {isDirect(cur.url)
              ? <video key={cur.url} src={cur.url} controls autoPlay playsInline style={pl} />
              : <iframe key={cur.url} src={cur.url} title={a.title} allowFullScreen allow="autoplay; fullscreen; picture-in-picture" style={pl} />}
            <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginTop: 10, gap: 8 }}>
              <button disabled={idx <= 0} onClick={() => play(eps[idx - 1])} style={navBtn(idx <= 0)}>‹ Sebelumnya</button>
              <span style={{ fontSize: 13, fontWeight: 600, textAlign: "center" }}>Episode {cur.n}{cur.title ? ` · ${cur.title}` : ""}</span>
              <button disabled={idx >= eps.length - 1} onClick={() => play(eps[idx + 1])} style={navBtn(idx >= eps.length - 1)}>Berikutnya ›</button>
            </div>
          </div>
        )}
        <div style={{ display: "flex", gap: 14 }}>
          <div style={{ width: 112, flexShrink: 0 }}><Cover a={a} /></div>
          <div style={{ minWidth: 0 }}>
            <div className="disp" style={{ fontSize: 20, fontWeight: 700, lineHeight: 1.2 }}>{a.title}</div>
            <div style={{ fontSize: 12.5, color: dim, margin: "4px 0 8px" }}>{[a.year, a.status, `${eps.length} episode`].filter(Boolean).join(" · ")}</div>
            <div style={{ display: "flex", flexWrap: "wrap", gap: 6, marginBottom: 12 }}>
              {(a.genres || []).map(x => <span key={x} style={{ fontSize: 11, padding: "3px 9px", borderRadius: 99, background: "rgba(255,255,255,0.1)" }}>{x}</span>)}
            </div>
            {resume && <button onClick={() => play(resume)} style={{ ...chip(true), display: "flex", alignItems: "center", gap: 6, padding: "9px 16px" }}><IcPlay s={14} />{hist[a.id] ? `Lanjutkan Ep ${resume.n}` : "Mulai nonton"}</button>}
          </div>
        </div>
        {a.synopsis && <p style={{ fontSize: 13.5, lineHeight: 1.6, color: "rgba(255,255,255,0.8)", margin: "16px 0 0" }}>{a.synopsis}</p>}
        <div className="disp" style={{ fontSize: 18, fontWeight: 700, margin: "20px 0 10px" }}>Episode</div>
        {eps.length === 0 && <div style={{ color: dim, fontSize: 13 }}>Belum ada episode.</div>}
        <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill,minmax(56px,1fr))", gap: 8 }}>
          {eps.map(e => (
            <button key={e.n} onClick={() => play(e)} aria-label={`Episode ${e.n}`} style={{ border: "none", cursor: "pointer", padding: "11px 0", borderRadius: 12, fontSize: 14, fontWeight: 700, color: e.n === ep ? "#fff" : seen.includes(e.n) ? dim : "#fff", background: e.n === ep ? "var(--accent)" : seen.includes(e.n) ? "rgba(255,255,255,0.05)" : "rgba(255,255,255,0.12)" }}>{e.n}</button>
          ))}
        </div>
      </div>
    </div>
  );
};

const HistoryScreen = ({ hist, catalog, onOpen }) => {
  const rows = Object.entries(hist).sort((x, y) => y[1].at - x[1].at);
  return (
    <div style={{ padding: "4px 18px 120px" }}>
      <div className="disp" style={{ fontSize: 22, fontWeight: 700, marginBottom: 12 }}>Riwayat</div>
      {rows.length === 0 && <Msg>Belum ada tontonan.</Msg>}
      {rows.map(([id, h]) => {
        const a = catalog.find(x => x.id === id);
        return (
          <button key={id} disabled={!a} onClick={() => a && onOpen(a)} style={{ display: "flex", alignItems: "center", gap: 12, width: "100%", textAlign: "left", background: "rgba(255,255,255,0.06)", border: "none", borderRadius: 16, padding: 10, marginBottom: 8, color: "#fff", cursor: a ? "pointer" : "default", opacity: a ? 1 : 0.5 }}>
            <div style={{ width: 48, flexShrink: 0 }}>{a ? <Cover a={a} /> : <Cover a={{ title: h.title }} />}</div>
            <div style={{ minWidth: 0, flex: 1 }}>
              <div style={{ fontWeight: 600, fontSize: 14, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{h.title}</div>
              <div style={{ fontSize: 12, color: dim }}>Terakhir: Episode {h.ep}{a ? "" : " · tidak ada di katalog"}</div>
            </div>
            {a && <IcChevron s={18} />}
          </button>
        );
      })}
    </div>
  );
};

const ProfileScreen = ({ profile, setProfile, hist, user, onLogout }) => {
  const fileRef = useRef();
  const [frameOpen, setFrameOpen] = useState(false);
  const eps = Object.values(hist).reduce((n, h) => n + (h.eps?.length || 0), 0);
  const onAvatar = async (e) => {
    const f = e.target.files?.[0]; e.target.value = "";
    if (!f) return;
    try { const avatar = await readImage(f, 400); setProfile(p => ({ ...p, avatar })); } catch {}
  };
  return (
    <div style={{ padding: "8px 18px 120px" }}>
      <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 10 }}>
        <div style={{ position: "relative" }}>
          <AvatarFrame profile={profile} size={84} />
          <button aria-label="Ganti foto" onClick={() => fileRef.current?.click()} style={{ position: "absolute", right: 14, bottom: 14, width: 30, height: 30, borderRadius: "50%", background: "var(--accent)", border: "2px solid var(--bg)", color: "#fff", display: "flex", alignItems: "center", justifyContent: "center", cursor: "pointer" }}><IcCamera s={13} /></button>
          <input ref={fileRef} type="file" accept="image/*" onChange={onAvatar} style={{ display: "none" }} />
        </div>
        <button onClick={() => setFrameOpen(true)} aria-haspopup="dialog" style={chip(false)}>Ganti bingkai</button>
        <input value={profile.name} maxLength={24} onChange={e => setProfile(p => ({ ...p, name: e.target.value || " " }))} aria-label="Nama" style={{ ...inputStyle, textAlign: "center", fontWeight: 700, fontSize: 18, maxWidth: 280 }} />
        <input value={profile.bio} maxLength={60} onChange={e => setProfile(p => ({ ...p, bio: e.target.value }))} aria-label="Bio" style={{ ...inputStyle, textAlign: "center", maxWidth: 280, color: dim }} />
        {user?.email && <div style={{ fontSize: 12, color: dim }}>{user.email}</div>}
      </div>
      <div style={{ display: "flex", gap: 10, margin: "22px 0" }}>
        {[[Object.keys(hist).length, "Anime ditonton"], [eps, "Episode ditonton"]].map(([n, l]) => (
          <div key={l} style={{ flex: 1, background: "rgba(255,255,255,0.06)", borderRadius: 16, padding: "14px 10px", textAlign: "center" }}>
            <div className="disp" style={{ fontSize: 24, fontWeight: 800 }}>{n}</div>
            <div style={{ fontSize: 12, color: dim }}>{l}</div>
          </div>
        ))}
      </div>
      <button onClick={onLogout} style={{ width: "100%", padding: 13, borderRadius: 14, border: "none", background: "rgba(239,68,68,0.15)", color: "#FCA5A5", fontWeight: 700, fontSize: 14, cursor: "pointer" }}>Keluar</button>
      {frameOpen && (
        <div onClick={() => setFrameOpen(false)} style={{ position: "fixed", inset: 0, zIndex: 250, background: "rgba(0,0,0,0.72)", display: "flex", alignItems: "center", justifyContent: "center", padding: 16 }}>
          <div role="dialog" aria-modal="true" aria-label="Pilih bingkai" onClick={e => e.stopPropagation()} style={{ width: "100%", maxWidth: 400, maxHeight: "86dvh", overflowY: "auto", background: "var(--panel)", borderRadius: 24, padding: 18, boxShadow: "0 24px 60px rgba(0,0,0,0.6)" }}>
            <div className="disp" style={{ fontSize: 20, fontWeight: 700, marginBottom: 14 }}>Pilih bingkai</div>
            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr 1fr", gap: 8 }}>
              {FRAMES.map(f => (
                <button key={f.id} aria-pressed={(profile.frame || "basic") === f.id} onClick={() => setProfile(p => ({ ...p, frame: f.id }))} style={frameTile((profile.frame || "basic") === f.id)}>
                  <AvatarFrame profile={{ ...profile, frame: f.id }} size={58} />
                  <span style={{ fontSize: 12, fontWeight: 600 }}>{f.name}</span>
                </button>
              ))}
            </div>
            <button onClick={() => setFrameOpen(false)} style={{ width: "100%", marginTop: 14, background: "var(--accent)", border: "none", borderRadius: 12, padding: 12, fontSize: 14, fontWeight: 700, color: "#fff", cursor: "pointer" }}>Selesai</button>
          </div>
        </div>
      )}
    </div>
  );
};

const TABS = [
  { id: "home", label: "Beranda", Icon: IcHome },
  { id: "history", label: "Riwayat", Icon: IcHistory },
  { id: "profile", label: "Profil", Icon: IcUser },
];
const BottomNav = ({ active, onChange }) => (
  <nav style={{ position: "fixed", left: 14, right: 14, bottom: "calc(env(safe-area-inset-bottom,0px) + 12px)", zIndex: 50, height: 64, display: "flex", borderRadius: 28, background: "var(--mini)", backdropFilter: "blur(24px)", WebkitBackdropFilter: "blur(24px)", border: "1px solid rgba(255,255,255,0.08)" }}>
    {TABS.map(({ id, label, Icon }) => {
      const on = active === id;
      return (
        <button key={id} onClick={() => onChange(id)} style={{ flex: 1, background: "none", border: "none", cursor: "pointer", display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", gap: 3, color: on ? "var(--accent-soft)" : "rgba(255,255,255,0.64)" }}>
          <div style={{ padding: "5px 16px", borderRadius: 99, background: on ? "rgba(var(--accent-rgb),0.18)" : "transparent" }}><Icon s={22} filled={on} /></div>
          <span style={{ fontSize: 10, fontWeight: on ? 700 : 500 }}>{label}</span>
        </button>
      );
    })}
  </nav>
);

const Header = ({ profile }) => (
  <div style={{ position: "sticky", top: "env(safe-area-inset-top,0px)", zIndex: 30, background: "rgba(var(--bg-rgb),0.92)", backdropFilter: "blur(20px)", padding: "14px 18px 10px", display: "flex", alignItems: "center", justifyContent: "space-between" }}>
    <div className="disp" style={{ fontSize: 24, fontWeight: 800, letterSpacing: -0.5 }}>SICAC</div>
    <AvatarFrame profile={profile} size={36} simple />
  </div>
);

// ─── ROOT ──────────────────────────────────────────────────────────────────
export default function SicacApp() {
  const [user, setUser] = useState(() => LS.get("sicac.user", null));
  const [profile, setProfile] = useState(() => LS.get("sicac.profile", { name: "Pengguna", bio: "Suka nonton anime", avatar: null, frame: "basic" }));
  const [hist, setHist] = useState(() => LS.get("sicac.history", {}));
  const [tab, setTab] = useState("home");
  const [open, setOpen] = useState(null);
  const [catalog, setCatalog] = useState([]);
  const [status, setStatus] = useState("loading");

  const load = () => {
    setStatus("loading");
    fetch(CATALOG_URL, { cache: "no-store" })
      .then(r => { if (!r.ok) throw new Error("http"); return r.json(); })
      .then(d => {
        setCatalog((Array.isArray(d.anime) ? d.anime : []).map(a => ({ ...a, episodes: [...(a.episodes || [])].sort((x, y) => x.n - y.n) })));
        setStatus("ok");
      })
      .catch(() => setStatus("error"));
  };
  useEffect(() => { load(); }, []);
  useEffect(() => { LS.set("sicac.profile", profile); }, [profile]);
  useEffect(() => { LS.set("sicac.history", hist); }, [hist]);

  const watch = (a, e) => setHist(h => {
    const p = h[a.id]?.eps || [];
    return { ...h, [a.id]: { ep: e.n, at: Date.now(), title: a.title, eps: p.includes(e.n) ? p : [...p, e.n] } };
  });
  const login = (u) => {
    setUser(u); LS.set("sicac.user", u);
    setProfile(p => ({ ...p, name: u.isGuest ? p.name : u.name, avatar: p.avatar || u.avatar }));
  };
  const logout = () => { setUser(null); setOpen(null); setTab("home"); try { localStorage.removeItem("sicac.user"); } catch {} };

  if (!user) return <GoogleLoginScreen onLogin={login} />;
  return (
    <div style={{ ...VARS, minHeight: "100dvh", background: "var(--bg)", color: "#fff", fontFamily: FONT }}>
      <style>{GLOBAL_CSS}</style>
      <Header profile={profile} />
      {tab === "home" && <HomeScreen catalog={catalog} status={status} onOpen={setOpen} reload={load} />}
      {tab === "history" && <HistoryScreen hist={hist} catalog={catalog} onOpen={setOpen} />}
      {tab === "profile" && <ProfileScreen profile={profile} setProfile={setProfile} hist={hist} user={user} onLogout={logout} />}
      <BottomNav active={tab} onChange={setTab} />
      {open && <DetailScreen key={open.id} a={open} hist={hist} onClose={() => setOpen(null)} onWatch={watch} />}
    </div>
  );
}
